import json
BP={"refPath":"/Game/Gameplay/UI/V2/WBP_UIReward.WBP_UIReward"}
OPS=json.loads("[{\"op\":\"AddWidgetIfMissing\",\"class\":\"/Script/UMG.HorizontalBox\",\"name\":\"RewardV2ContextRow\",\"parent\":\"RewardV2Column\",\"index\":1,\"slot\":{\"Padding\":{\"Left\":8,\"Top\":8,\"Right\":8,\"Bottom\":8},\"HorizontalAlignment\":\"HAlign_Fill\"}},{\"op\":\"MoveWidget\",\"name\":\"RewardV2SourceTitle\",\"expected_previous_parent\":\"RewardV2Column\",\"parent\":\"RewardV2ContextRow\",\"index\":0,\"slot\":{\"Size\":{\"SizeRule\":\"Fill\",\"Value\":1},\"HorizontalAlignment\":\"HAlign_Fill\",\"VerticalAlignment\":\"VAlign_Center\",\"Padding\":{\"Left\":8,\"Top\":2,\"Right\":12,\"Bottom\":4}}},{\"op\":\"MoveWidget\",\"name\":\"RewardV2CountdownBounds\",\"expected_previous_parent\":\"RewardV2HeaderRow\",\"parent\":\"RewardV2ContextRow\",\"index\":1,\"slot\":{\"Size\":{\"SizeRule\":\"Automatic\",\"Value\":1},\"HorizontalAlignment\":\"HAlign_Right\",\"VerticalAlignment\":\"VAlign_Center\",\"Padding\":{\"Left\":12,\"Top\":0,\"Right\":0,\"Bottom\":0}}},{\"op\":\"SetSlotProperties\",\"name\":\"RewardV2TitleBounds\",\"expected_parent\":\"RewardV2HeaderRow\",\"values\":{\"Size\":{\"SizeRule\":\"Fill\",\"Value\":1},\"HorizontalAlignment\":\"HAlign_Center\",\"VerticalAlignment\":\"VAlign_Center\"}},{\"op\":\"SetSlotProperties\",\"name\":\"RewardV2Frame\",\"expected_parent\":\"RewardV2Size\",\"values\":{\"VerticalAlignment\":\"VAlign_Top\",\"HorizontalAlignment\":\"HAlign_Fill\"}},{\"op\":\"SetProperties\",\"name\":\"RewardV2Size\",\"values\":{\"bOverride_HeightOverride\":false,\"bOverride_MinDesiredWidth\":true,\"MinDesiredWidth\":1040,\"bOverride_MaxDesiredWidth\":true,\"MaxDesiredWidth\":1580}},{\"op\":\"SetProperties\",\"name\":\"RewardV2Frame\",\"values\":{\"ContourPoints\":[{\"X\":0,\"Y\":0.14},{\"X\":0.24,\"Y\":0.14},{\"X\":0.24,\"Y\":0},{\"X\":0.76,\"Y\":0},{\"X\":0.76,\"Y\":0.14},{\"X\":1,\"Y\":0.14},{\"X\":1,\"Y\":1},{\"X\":0,\"Y\":1}]}},{\"op\":\"SetProperties\",\"name\":\"RewardV2Cards\",\"values\":{\"bExplicitWrapSize\":true,\"WrapSize\":1116}}]")
EXPECTED=json.loads("{\"RewardV2Column\":\"VerticalBox\",\"RewardV2HeaderRow\":\"HorizontalBox\",\"RewardV2TitleBounds\":\"SizeBox\",\"RewardV2CountdownBounds\":\"SizeBox\",\"RewardV2SourceTitle\":\"TextBlock\",\"RewardV2Frame\":\"MCUniversalUIWidget\",\"RewardV2Cards\":\"WrapBox\",\"RewardV2Size\":\"SizeBox\"}")
U="UMGToolSet.UMGToolSet."
O="editor_toolset.toolsets.object.ObjectTools."
def call(name,args):return execute_tool(name,json.dumps(args))["returnValue"]
def info():return call(U+"GetWidgets",{"widgetBlueprint":BP})
def update(obj,wanted):
    schema=json.loads(call(O+"list_properties",{"instance":obj}))
    normalize=lambda x:x.lower().replace("_","")
    values={}
    for name,value in wanted.items():
        actual=next((key for key in schema if normalize(key)==normalize(name)),None)
        assert actual,(name,list(schema));values[actual]=value
    current=json.loads(call(O+"get_properties",{"instance":obj,"properties":list(values)}))
    for key,value in values.items():
        if key.lower()=="contourpoints" and len(current[key])!=len(value):
            padded=current[key][:len(value)]
            while len(padded)<len(value):padded.append({"x":0,"y":0})
            assert call(O+"set_properties",{"instance":obj,"values":json.dumps({key:padded})})
    assert call(O+"set_properties",{"instance":obj,"values":json.dumps(values)})
def run():
    assert not call("editor_toolset.toolsets.asset.AssetTools.is_dirty",{"asset_path":"/Game/Gameplay/UI/V2/WBP_UIReward"})
    d={w["widgetName"]:w for w in info()["widgets"]}
    for name,cls in EXPECTED.items():
        assert name in d and d[name]["widgetClassPath"]["refPath"].endswith("."+cls),(name,cls)
    changed=[]
    for op in OPS:
        kind=op["op"];name=op["name"]
        if kind=="AddWidgetIfMissing":
            if name not in d:d[name]=call(U+"AddWidget",{"widgetBlueprint":BP,"widgetClass":{"refPath":op["class"]},"widgetDisplayName":name,"parentWidget":d[op["parent"]]["widget"],"childIndex":op["index"]})
            assert d[name]["parent"]==d[op["parent"]]["widget"]
            update(d[name]["slot"],op["slot"])
        elif kind=="MoveWidget":
            old=d[name]["parent"]
            assert old==d[op["parent"]]["widget"] or old==d[op["expected_previous_parent"]]["widget"],name
            if old!=d[op["parent"]]["widget"]:
                d[name]=call(U+"MoveWidget",{"widgetBlueprint":BP,"widget":d[name]["widget"],"newParent":d[op["parent"]]["widget"],"childIndex":op["index"]})
            update(d[name]["slot"],op["slot"])
        elif kind=="SetSlotProperties":
            assert d[name]["parent"]==d[op["expected_parent"]]["widget"]
            update(d[name]["slot"],op["values"])
        elif kind=="SetProperties":update(d[name]["widget"],op["values"])
        else:assert False,kind
        changed.append(name)
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":BP})
    assert call("editor_toolset.toolsets.asset.AssetTools.save_assets",{"asset_paths":["/Game/Gameplay/UI/V2/WBP_UIReward"]})
    root={"refPath":"/Game/Gameplay/UI/V2/WBP_UIRoot.WBP_UIRoot"}
    rd={w["widgetName"]:w for w in call(U+"GetWidgets",{"widgetBlueprint":root})["widgets"]}
    for name in ("UnifiedReward","UnifiedGameplayMenu"):update(rd[name]["slot"],{"HorizontalAlignment":"HAlign_Center"})
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":root})
    assert call("editor_toolset.toolsets.asset.AssetTools.save_assets",{"asset_paths":["/Game/Gameplay/UI/V2/WBP_UIRoot"]})
    return {"saved":True,"changed":changed,"modalAlignment":"Centered Reward and GameplayMenu"}
